function seed({ run, get, now, setSetting, settings }) {
  const cur = settings();
  for (const [k, v] of Object.entries(DEFAULT_SETTINGS)) {
    if (!(k in cur)) setSetting(k, v);
    else if (v && typeof v === 'object' && !Array.isArray(v) && cur[k] && typeof cur[k] === 'object') {
      const merged = { ...v, ...cur[k] };
      if (JSON.stringify(merged) !== JSON.stringify(cur[k])) setSetting(k, merged);
    }
  }

  T.forEach(([key, grp, label, ru, kk, ml], i) => {
    run(`INSERT INTO texts(key, grp, label, ru, kk, multiline, sort) VALUES(?,?,?,?,?,?,?)
         ON CONFLICT(key) DO UPDATE SET grp = excluded.grp, label = excluded.label, multiline = excluded.multiline, sort = excluded.sort`,
      key, grp, label, ru, kk, ml, i);
  });

  if (!get('SELECT 1 FROM service_categories LIMIT 1')) {
    CATEGORIES.forEach(([slug, tru, tkk, icon, iru, ikk], ci) => {
      const r = run('INSERT INTO service_categories(slug, title_ru, title_kk, intro_ru, intro_kk, icon, sort) VALUES(?,?,?,?,?,?,?)', slug, tru, tkk, iru, ikk, icon, ci);
      SERVICES[slug].forEach(([sr, dr, sk, dk], si) => {
        run('INSERT INTO services(category_id, title_ru, title_kk, desc_ru, desc_kk, sort) VALUES(?,?,?,?,?,?)', r.lastInsertRowid, sr, sk, dr, dk, si);
      });
    });
  }
  if (!get('SELECT 1 FROM faq LIMIT 1')) {
    FAQ.forEach(([qr, ar, qk, ak], i) => run('INSERT INTO faq(q_ru, q_kk, a_ru, a_kk, sort) VALUES(?,?,?,?,?)', qr, qk, ar, ak, i));
  }
  if (!get("SELECT 1 FROM pages WHERE slug = 'politika-konfidencialnosti'")) {
    run(`INSERT INTO pages(slug, title_ru, title_kk, body_ru, body_kk, desc_ru, desc_kk, in_footer, system, updated_at)
         VALUES(?,?,?,?,?,?,?,1,1,?)`, 'politika-konfidencialnosti', 'Политика конфиденциальности', 'Құпиялылық саясаты',
      PRIVACY_RU, PRIVACY_KK, 'Порядок сбора, обработки и защиты персональных данных пользователей сайта.', 'Сайт пайдаланушыларының дербес деректерін жинау, өңдеу және қорғау тәртібі.', now());
  }
  if (!get('SELECT 1 FROM posts LIMIT 1')) {
    run(`INSERT INTO posts(slug, category, title_ru, title_kk, excerpt_ru, excerpt_kk, body_ru, body_kk, published, published_at, updated_at)
         VALUES(?,?,?,?,?,?,?,?,1,?,?)`, 'zapustili-novyy-sayt', 'company',
      'Запустили новый сайт компании', 'Компанияның жаңа сайты іске қосылды',
      'Онлайн-калькулятор стоимости, перечень услуг и быстрые заявки — теперь на сайте.',
      'Қызмет құнының онлайн-калькуляторы, қызметтер тізімі және жылдам өтінімдер — енді сайтта.',
      LAUNCH_POST_RU, LAUNCH_POST_KK, now(), now());
  }
  // правила оплаты и возврата — системная страница на трёх языках
  if (!get("SELECT 1 FROM pages WHERE slug = 'pravila-oplaty'")) {
    run(`INSERT INTO pages(slug, title_ru, title_kk, title_en, body_ru, body_kk, body_en, desc_ru, desc_kk, desc_en, in_footer, sort, system, updated_at)
         VALUES(?,?,?,?,?,?,?,?,?,?,1,5,1,?)`, 'pravila-oplaty', PAY_RULES.ru[0], PAY_RULES.kk[0], PAY_RULES.en[0],
      PAY_RULES.ru[2], PAY_RULES.kk[2], PAY_RULES.en[2], PAY_RULES.ru[1], PAY_RULES.kk[1], PAY_RULES.en[1], now());
  }

  // видео и сертификаты заказчика
  if (!get('SELECT 1 FROM videos LIMIT 1')) {
    VIDEOS.forEach(([f, topic, lng, home, ru, kk, en], i) => run('INSERT INTO videos(title_ru, title_kk, title_en, topic, lang, file, poster, on_home, sort) VALUES(?,?,?,?,?,?,?,?,?)',
      ru, kk, en, topic, lng, `/media/video/${f}.mp4`, `/media/video/${f}.jpg`, home, i));
  }
  if (!get('SELECT 1 FROM certificates LIMIT 1')) {
    CERTS.forEach(([f, ru, kk, en, dru, dkk, den], i) => run('INSERT INTO certificates(title_ru, title_kk, title_en, desc_ru, desc_kk, desc_en, image, sort) VALUES(?,?,?,?,?,?,?,?)',
      ru, kk, en, dru, dkk, den, `/img/certs/${f}.jpg`, i));
  }
  // старое фото команды заказчик попросил убрать — заменяем, если его не меняли в панели
  {
    const im = settings().images || {};
    const next = { ...im };
    if (!im.hero || im.hero === '/img/team.webp') next.hero = '/img/team/hero.webp';
    // фото на «Новостях» — горизонтальный кадр, чтобы не обрезать головы
    if (!im.team || im.team === '/img/team.jpg' || im.team === '/img/team/team-2.webp') next.team = '/img/team/team-2-wide.webp';
    if (!im.about) next.about = '/img/team/team-1.webp';
    if (JSON.stringify(next) !== JSON.stringify(im)) setSetting('images', next);
    const so = settings().socials || {};
    if (!so.instagram) setSetting('socials', { ...so, instagram: 'https://www.instagram.com/dialog_uchet/' });
  }

  // английская версия: заполняет только пустые поля, правки из панели не трогает
  let EN = null;
  try { EN = require('./seed-en'); } catch { EN = null; }
  if (!EN) return;
  const st = settings();
  for (const [k, v] of Object.entries(EN.settings || {})) if (!st[k]) setSetting(k, v);
  if (Array.isArray(st.offices) && EN.offices) {
    let changed = false;
    const offices = st.offices.map((o, i) => {
      const e = EN.offices.find((x, j) => j === i && DEFAULT_SETTINGS.offices[j] && DEFAULT_SETTINGS.offices[j].city_ru === o.city_ru);
      if (e && !o.city_en) { changed = true; return { ...o, ...e }; }
      return o;
    });
    if (changed) setSetting('offices', offices);
  }
  for (const [k, v] of Object.entries(EN.texts || {})) run("UPDATE texts SET en = ? WHERE key = ? AND en = ''", v, k);
  for (const [slug, [ti, intro]] of Object.entries(EN.categories || {})) {
    run("UPDATE service_categories SET title_en = ? WHERE slug = ? AND title_en = ''", ti, slug);
    run("UPDATE service_categories SET intro_en = ? WHERE slug = ? AND intro_en = ''", intro, slug);
  }
  for (const [slug, list] of Object.entries(EN.services || {})) {
    (SERVICES[slug] || []).forEach(([ru], i) => {
      if (!list[i]) return;
      run("UPDATE services SET title_en = ? WHERE title_ru = ? AND title_en = ''", list[i][0], ru);
      run("UPDATE services SET desc_en = ? WHERE title_ru = ? AND desc_en = ''", list[i][1], ru);
    });
  }
  FAQ.forEach(([qr], i) => {
    const e = (EN.faq || [])[i];
    if (e) run("UPDATE faq SET q_en = ?, a_en = ? WHERE q_ru = ? AND q_en = ''", e[0], e[1], qr);
  });
  for (const [slug, p] of Object.entries(EN.pages || {})) run("UPDATE pages SET title_en = ?, body_en = ?, desc_en = ? WHERE slug = ? AND title_en = ''", p.title, p.body, p.desc, slug);
  for (const [slug, p] of Object.entries(EN.posts || {})) run("UPDATE posts SET title_en = ?, excerpt_en = ?, body_en = ? WHERE slug = ? AND title_en = ''", p.title, p.excerpt, p.body, slug);
}

module.exports = { seed, DEFAULT_SETTINGS };
